begin;
set local search_path=public,extensions;
select plan(14);

select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig @> array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'complete_catalog_%_version_identity'),'compatibility functions are SECURITY DEFINER with fixed pg_catalog search_path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'complete_catalog_%_version_identity' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'all five compatibility trigger functions are non-executable by every API runtime role');
select has_trigger('public','catalog_library_versions','catalog_library_versions_complete_identity','library version compatibility trigger exists');
select has_trigger('public','catalog_category_versions','catalog_category_versions_complete_identity','category version compatibility trigger exists');
select has_trigger('public','catalog_subcategory_versions','catalog_subcategory_versions_complete_identity','subcategory version compatibility trigger exists');
select has_trigger('public','catalog_service_versions','catalog_service_versions_complete_identity','service version compatibility trigger exists');
select has_trigger('public','catalog_service_subcategory_link_versions','catalog_link_versions_complete_identity','link version compatibility trigger exists');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('e2700000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-compat@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by) values ('e2710000-0000-0000-0000-000000000001','P06 Compatibility Steward','P06 Compatibility','ACTIVE','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by) values ('e2720000-0000-0000-0000-000000000001','COMPAT_LIB','compat-lib','e2710000-0000-0000-0000-000000000001','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by) values ('e2720000-0000-0000-0000-000000000002','OTHER_LIB','other-lib','e2710000-0000-0000-0000-000000000001','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_categories(id,library_id,code,slug,created_by) values ('e2730000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001','COMPAT_CAT','compat-category','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_subcategories(id,library_id,category_id,code,slug,created_by) values ('e2740000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001','e2730000-0000-0000-0000-000000000001','COMPAT_SUB','compat-subcategory','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_services(id,library_id,primary_subcategory_id,code,slug,created_by) values ('e2750000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001','e2740000-0000-0000-0000-000000000001','COMPAT_SERVICE','compat-service','e2700000-0000-0000-0000-000000000001');
insert into public.catalog_service_subcategory_links(id,service_id,subcategory_id,library_id,link_type,created_by) values ('e2760000-0000-0000-0000-000000000001','e2750000-0000-0000-0000-000000000001','e2740000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001','PRIMARY','e2700000-0000-0000-0000-000000000001');

insert into public.catalog_library_versions(id,library_id,version,name_fr,name_ar,description_fr,description_ar,icon_key,sort_order,change_reason,content_hash,created_by) values ('e2770000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001',1,'Bibliothèque compatible','مكتبة متوافقة','Description compatible','وصف متوافق','layers',1,'Ancien writer compatible',repeat('1',64),'e2700000-0000-0000-0000-000000000001');
insert into public.catalog_category_versions(id,category_id,library_id,version,name_fr,name_ar,description_fr,description_ar,sort_order,change_reason,content_hash,created_by) values ('e2780000-0000-0000-0000-000000000001','e2730000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001',1,'Catégorie compatible','فئة متوافقة','Description compatible','وصف متوافق',1,'Ancien writer compatible',repeat('2',64),'e2700000-0000-0000-0000-000000000001');
insert into public.catalog_subcategory_versions(id,subcategory_id,library_id,version,name_fr,name_ar,description_fr,description_ar,sort_order,change_reason,content_hash,created_by) values ('e2790000-0000-0000-0000-000000000001','e2740000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000001',1,'Sous-catégorie compatible','فئة فرعية متوافقة','Description compatible','وصف متوافق',1,'Ancien writer compatible',repeat('3',64),'e2700000-0000-0000-0000-000000000001');
