select is((select code||':'||slug from public.catalog_library_versions where id='e2770000-0000-0000-0000-000000000001'),'COMPAT_LIB:compat-lib','library snapshot identity is completed from its identity row');
select is((select code||':'||slug from public.catalog_category_versions where id='e2780000-0000-0000-0000-000000000001'),'COMPAT_CAT:compat-category','category snapshot identity is completed from its identity row');
select is((select category_id::text||':'||code||':'||slug from public.catalog_subcategory_versions where id='e2790000-0000-0000-0000-000000000001'),'e2730000-0000-0000-0000-000000000001:COMPAT_SUB:compat-subcategory','subcategory parent and snapshot identity are completed');
select is((select primary_subcategory_id::text||':'||code||':'||slug from public.catalog_service_versions where id='e27a0000-0000-0000-0000-000000000001'),'e2740000-0000-0000-0000-000000000001:COMPAT_SERVICE:compat-service','service parent and snapshot identity are completed');
select is((select service_id::text||':'||subcategory_id::text||':'||link_type from public.catalog_service_subcategory_link_versions where id='e27b0000-0000-0000-0000-000000000001'),'e2750000-0000-0000-0000-000000000001:e2740000-0000-0000-0000-000000000001:PRIMARY','link endpoints and type are completed');
select lives_ok($$insert into public.catalog_library_versions(id,library_id,version,code,slug,name_fr,name_ar,description_fr,description_ar,icon_key,sort_order,change_reason,content_hash,created_by) values ('e2770000-0000-0000-0000-000000000002','e2720000-0000-0000-0000-000000000001',2,'COMPAT_LIB','compat-lib','Version explicite','نسخة صريحة','Description explicite','وصف صريح','layers',2,'Valeurs explicites conservées',repeat('6',64),'e2700000-0000-0000-0000-000000000001')$$,'matching explicit snapshot identity remains supported');
select throws_ok($$insert into public.catalog_category_versions(id,category_id,library_id,version,name_fr,name_ar,description_fr,description_ar,sort_order,change_reason,content_hash,created_by) values ('e2780000-0000-0000-0000-000000000009','e2730000-0000-0000-0000-000000000001','e2720000-0000-0000-0000-000000000002',9,'Catégorie croisée','فئة متقاطعة','Doit être refusée','يجب رفضها',9,'Périmètre bibliothèque invalide',repeat('9',64),'e2700000-0000-0000-0000-000000000001')$$,'23514','CATALOG_CATEGORY_VERSION_IDENTITY_MISMATCH','cross-library identity mismatch fails closed in the compatibility trigger');

select * from finish();
rollback;
